def analyze(i,o):
    H,W=len(i),len(i[0])
    cols={v for r in i for v in r}
    special=[v for v in cols if v not in (0,) and sum(r.count(v) for r in i)<15]
    s=special[0]
    cells=[(r,c) for r in range(H) for c in range(W) if i[r][c]==s]
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    S={(r-r0,c-c0) for r,c in cells}
    h=max(r for r,c in S)+1; w=max(c for r,c in S)+1
    found=[]
    for r in range(H-h+1):
        for c in range(W-w+1):
            if all(i[r+dr][c+dc]==0 for dr,dc in S):
                found.append((r,c))
    out=[[s if (r-dr,c-dc) in S and (dr,dc) in found else v for dc,v in enumerate(row)] for dr,row in enumerate(i)]
    # instead: stamp
    out=[row[:] for row in i]
    for r,c in found:
        for dr,dc in S: out[r+dr][c+dc]=s
    ok = out==o
    diff=[(r,c,i[r][c],o[r][c]) for r in range(H) for c in range(W) if out[r][c]!=o[r][c]]
    return s,S,found,ok,diff
